package com.retail.notification;
import jakarta.persistence.*; import jakarta.transaction.Transactional; import jakarta.validation.constraints.*; import jakarta.ws.rs.*; import jakarta.ws.rs.core.MediaType; import java.util.*;
@Path("/") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) public class NotificationResource { @PersistenceContext EntityManager em; public record NotificationRequest(@NotNull UUID orderId,@Email @NotBlank String recipient,@NotBlank @Size(max=60) String eventType,@NotBlank @Size(max=2000) String message){}
 @GET @Path("api/ping") @Produces(MediaType.TEXT_PLAIN) public String ping(){return "Hello from Notification Service";}
 @POST @Path("internal/notifications") @Transactional public Map<String,Object> create(@jakarta.validation.Valid NotificationRequest r){List<?> q=em.createNativeQuery("select id from notifications where order_id=?1 and event_type=?2").setParameter(1,r.orderId()).setParameter(2,r.eventType()).getResultList();if(!q.isEmpty())return out((UUID)q.getFirst(),r);UUID id=UUID.randomUUID();em.createNativeQuery("insert into notifications(id,order_id,recipient,event_type,message) values(?1,?2,?3,?4,?5)").setParameter(1,id).setParameter(2,r.orderId()).setParameter(3,r.recipient()).setParameter(4,r.eventType()).setParameter(5,r.message()).executeUpdate();return out(id,r);}
 @GET @Path("internal/notifications/{orderId}") public List<Map<String,Object>> byOrder(@PathParam("orderId") UUID id){List<?>q=em.createNativeQuery("select id,recipient,event_type,message,created_at from notifications where order_id=?1 order by created_at").setParameter(1,id).getResultList();List<Map<String,Object>>out=new ArrayList<>();for(Object row:q){Object[]v=(Object[])row;out.add(Map.of("id",v[0],"orderId",id,"recipient",v[1],"eventType",v[2],"message",v[3],"createdAt",v[4].toString()));}return out;} private static Map<String,Object> out(UUID id,NotificationRequest r){return Map.of("id",id,"orderId",r.orderId(),"recipient",r.recipient(),"eventType",r.eventType(),"message",r.message());}}
